AND (I.INQUIRY_TITLE LIKE CONCAT('%', #{keyword}, '%') OR I.INQUIRY_CONTENT LIKE CONCAT('%', #{keyword}, '%') OR U.NICKNAME LIKE CONCAT('%', #{keyword}, '%') OR U.USER_EMAIL LIKE CONCAT('%', #{keyword}, '%'))
